// Builds the exact JSON string that will be signed AND sent. The HMAC is over
// `${timestamp}.${rawBody}`, so rawBody must reach the HTTP node byte-for-byte —
// never let a downstream node re-serialize it.

const ORG_SLUG = 'dulong-downs-didi';   // per-client constant; must match PLAT_ORG_REGISTRY

const m = $input.item.json ?? {};

// Gmail Trigger sets an `id`; the Manual Trigger yields an empty item, in which
// case we send a synthetic message so signing + transport can be proven before
// a Gmail credential exists.
const isGmail = Boolean(m.id);

// Gmail field names differ between simple/raw modes — read defensively.
const header = (name) => {
  const hs = m.payload?.headers ?? m.headers ?? [];
  const hit = Array.isArray(hs) ? hs.find((h) => String(h.name).toLowerCase() === name) : null;
  return hit?.value ?? '';
};

const payload = isGmail
  ? {
      orgSlug: ORG_SLUG,
      channel: 'email',
      externalId: String(m.id),                       // Gmail message id = dedup key
      from: m.from?.value?.[0]?.address || m.From || m.from || header('from'),
      subject: m.subject || m.Subject || header('subject'),
      body: m.textPlain || m.text || m.textHtml || m.snippet || '',
      receivedAt: m.date || m.Date || new Date().toISOString(),
    }
  : {
      orgSlug: ORG_SLUG,
      channel: 'email',
      externalId: `n8n-test-${Date.now()}`,           // fresh id each run = no dedup
      from: 'test@aequilibri.com',
      subject: 'n8n connectivity test',
      body: 'Hi team, please order 40 sheets of 13mm plasterboard for the Riverside job by Friday.',
      receivedAt: new Date().toISOString(),
    };

const rawBody = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000).toString();

return {
  json: {
    rawBody,
    ts,
    signBase: `${ts}.${rawBody}`,   // the Crypto node HMACs exactly this
    isTest: !isGmail,
  },
};
